const tasks = $input.all().map(item => item.json);

if (tasks.length === 0) {
  return [{
    json: {
      hasTasks: false,
      taskCount: 0,
      summaryData: "There are no pending academic tasks."
    }
  }];
}

const totalTasks = tasks.length;

const urgentTasks = tasks.filter(
  task => task.urgency === "Urgent"
);

const overdueTasks = tasks.filter(
  task => task.urgency === "Overdue"
);

const highPriorityTasks = tasks.filter(
  task => task.priority === "High"
);

const upcomingTasks = tasks.filter(
  task => Number(task.days_remaining) >= 0 &&
          Number(task.days_remaining) <= 3
);

const taskList = tasks.map((task, index) => {
  return `${index + 1}. ${task.subject} — ${task.task}
Deadline: ${task.deadline}
Days remaining: ${task.days_remaining}
Priority: ${task.priority}
Urgency: ${task.urgency}`;
}).join("\n\n");

const summaryData = `
Total pending tasks: ${totalTasks}
Urgent tasks: ${urgentTasks.length}
Overdue tasks: ${overdueTasks.length}
High-priority tasks: ${highPriorityTasks.length}
Tasks due within 3 days: ${upcomingTasks.length}

Tasks:

${taskList}
`;

return [{
  json: {
    hasTasks: true,
    taskCount: totalTasks,
    summaryData
  }
}];

